import{_ as a,a as r,c as t,ac as i}from"./chunks/framework.BSuaGltH.js";const h=JSON.parse('{"title":"指标：序列、标签、Counter 与直方图","description":"从指标身份与抓取入口接续到基数、类型和统计口径。","frontmatter":{"title":"指标：序列、标签、Counter 与直方图","description":"从指标身份与抓取入口接续到基数、类型和统计口径。","showdocs":{"topics":[{"id":"metrics","title":"指标与可视化","link":"/topics/metrics/"}],"kind":"知识专题","scope":"general","audience":"general","group":"容器与运维","seriesTitle":"指标与可视化机制与任务课程","summary":"从指标身份与抓取入口接续到基数、类型和统计口径。","status":"active","related":[{"title":"指标与可视化：配置指标采集与 Grafana 面板","link":"/systems/logging-monitoring/metrics/plus/practice/application","kind":"开发与配置实践","scope":"general","audience":"general"},{"title":"指标与面板：空图、统计口径与故障复盘","link":"/systems/logging-monitoring/metrics/diagnosis","kind":"排错与诊断","scope":"general","audience":"general"},{"title":"指标与可视化：容量、录制规则与面板发布","link":"/systems/logging-monitoring/metrics/plus/practice/operations","kind":"知识专题","scope":"general","audience":"general"},{"title":"Grafana 多数据源与面板配置","link":"/systems/logging-monitoring/metrics/plus/subjects/grafana-data-sources","kind":"知识专题","scope":"general","audience":"general"}],"prev":false,"next":{"text":"指标与可视化：配置指标采集与 Grafana 面板","link":"/systems/logging-monitoring/metrics/plus/practice/application"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"指标与可视化：配置指标采集与 Grafana 面板","link":"/systems/logging-monitoring/metrics/plus/practice/application"}},"headers":[],"relativePath":"systems/logging-monitoring/metrics/metric-model.md","filePath":"systems/logging-monitoring/metrics/metric-model.md"}'),s={name:"systems/logging-monitoring/metrics/metric-model.md"};function o(n,e,l,p,c,m){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="指标-序列、标签、counter-与直方图" tabindex="-1">指标：序列、标签、Counter 与直方图 <a class="header-anchor" href="#指标-序列、标签、counter-与直方图" aria-label="Permalink to &quot;指标：序列、标签、Counter 与直方图&quot;">​</a></h1><h2 id="part-1" tabindex="-1">采样、时间序列与查询入门 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;采样、时间序列与查询入门 {#part-1}&quot;">​</a></h2><p>指标与可视化先确定测量对象、单位和时间窗口，再选择 counter、gauge 或 histogram。查询聚合必须保留正确分母；面板能显示曲线，并不证明它表达了正确业务含义。</p><h3 id="part-1-model" tabindex="-1">指标序列模型 <a class="header-anchor" href="#part-1-model" aria-label="Permalink to &quot;指标序列模型 {#part-1-model}&quot;">​</a></h3><p>指标序列模型由指标名与完整label集合唯一确定，样本是某时刻的值。一次请求的日志不能代替连续采样；同名指标换一个route标签值就是新序列。Prometheus按目标定期抓取，Grafana通过数据源查询存储，面板本身不存放业务指标。需要先理解job代表采集任务、instance代表具体目标，再看status/route等业务维度。</p><h3 id="part-1-promql" tabindex="-1">PromQL查询入口 <a class="header-anchor" href="#part-1-promql" aria-label="Permalink to &quot;PromQL查询入口 {#part-1-promql}&quot;">​</a></h3><p>指标PromQL入口先选择原始指标和明确label过滤，再逐步加入rate与sum，不能从复杂仪表盘JSON倒猜原始数据存在。即时查询返回一个求值时刻，区间查询在多个步长重复求值；图表步长不同可能看起来不同，不代表原始数据变了。命令或HTTP查询接口会访问真实Prometheus。</p><h3 id="part-1-scrape" tabindex="-1">抓取与权限前置 <a class="header-anchor" href="#part-1-scrape" aria-label="Permalink to &quot;抓取与权限前置 {#part-1-scrape}&quot;">​</a></h3><p>指标抓取前置要求Prometheus进程可达Exporter，Exporter只暴露必要统计并用网络/TLS/身份保护。up是抓取目标状态，不表示应用全部功能正常；健康页面成功也不证明/metrics指标有效。配置127.0.0.1:9109只适合同网络命名空间，容器里的回环并不是宿主机。不要为了便于Grafana访问就向全网开放未认证的Prometheus。</p><h3 id="part-1-selfcheck" tabindex="-1">本篇练习与参考解答 <a class="header-anchor" href="#part-1-selfcheck" aria-label="Permalink to &quot;本篇练习与参考解答 {#part-1-selfcheck}&quot;">​</a></h3><p>练习：Grafana连得上浏览器是否意味着它能访问Prometheus？</p><details><summary>参考解答</summary><p>不意味着。Grafana服务端须能访问配置url，容器内回环指自己，还需核对后端授权与TLS。</p></details><h3 id="part-1-references" tabindex="-1">核对资料与相邻阅读 <a class="header-anchor" href="#part-1-references" aria-label="Permalink to &quot;核对资料与相邻阅读 {#part-1-references}&quot;">​</a></h3><ul><li><p><a href="https://prometheus.io/docs/prometheus/latest/configuration/alerting_rules/" target="_blank" rel="noopener noreferrer">Prometheus 3.x当前规则文档核对</a></p></li><li><p><a href="https://grafana.com/docs/grafana/latest/administration/provisioning/" target="_blank" rel="noopener noreferrer">Grafana provisioning核对</a></p></li><li><p><a href="https://prometheus.io/docs/prometheus/2.55/querying/functions/" target="_blank" rel="noopener noreferrer">PromQL函数2.55</a></p></li><li><p><a href="https://grafana.com/docs/grafana/latest/datasources/prometheus/configure/" target="_blank" rel="noopener noreferrer">Grafana数据源</a></p></li><li><p><a href="https://github.com/prometheus/docs/blob/main/docs/tutorials/understanding_metric_types.md" target="_blank" rel="noopener noreferrer">指标类型官方教程</a></p></li></ul><p>继续阅读<a href="#part-2-types">机制</a>、<a href="/systems/logging-monitoring/metrics/plus/practice/application#files">完整实践</a>、<a href="/systems/logging-monitoring/metrics/plus/practice/operations#capacity">运维</a>、<a href="/systems/logging-monitoring/metrics/diagnosis#part-1-empty">诊断</a>与<a href="/systems/logging-monitoring/metrics/diagnosis#part-2-exercise">复习</a>。</p><h2 id="part-2" tabindex="-1">指标类型、标签基数与聚合 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;指标类型、标签基数与聚合 {#part-2}&quot;">​</a></h2><p>先明确指标类型/单位、抓取窗口与数据源 UID，再对照<a href="/systems/logging-monitoring/metrics/plus/practice/application#source">配套示例</a>理解原始序列、rate 聚合、空数据和面板单位。</p><p>核对日期2026-10-17；适用范围：机制按核对时Prometheus 3.x官方文档的稳定共同子集说明；示例另固定Prometheus 2.55与Grafana OSS 11.6教学配置族，归档族不是生产安装建议。新版新增或实验功能未默认启用，实际升级仍需独立兼容与安全评估。示例未执行；真实环境仍需验证产品配置、权限、连通与恢复结果。先读<a href="#part-1-model">起点</a>理解前置，再按章节完成推演。</p><h3 id="part-2-types" tabindex="-1">Counter和Gauge <a class="header-anchor" href="#part-2-types" aria-label="Permalink to &quot;Counter和Gauge {#part-2-types}&quot;">​</a></h3><p>指标类型选择决定查询语义：Counter累计递增并可在进程重启时归零，Gauge可上下变化表示当前值。checkout_requests_total应先按每条序列求rate，再按status聚合，防止先sum掩盖单实例重置。inflight_requests应直接观察当前值，给Gauge求rate虽可能被语法接受却常无业务意义。单位放名称与说明中，毫秒与秒混用会让阈值差千倍。</p><h3 id="part-2-cardinality" tabindex="-1">Label基数预算 <a class="header-anchor" href="#part-2-cardinality" aria-label="Permalink to &quot;Label基数预算 {#part-2-cardinality}&quot;">​</a></h3><p>指标标签基数是所有label组合产生的序列数量，route10种、status5种、instance20个最多形成1000种组合，还要乘指标族数量。不要把request_id、用户ID或完整URL放label；将动态路由归一为/cart/{id}等模板，在日志保存请求级证据。删除label只能减少后续序列，历史块不会立即消失；必须从埋点、采集过滤和保留期限共同控制容量。</p><h3 id="part-2-histogram" tabindex="-1">直方图和分位数 <a class="header-anchor" href="#part-2-histogram" aria-label="Permalink to &quot;直方图和分位数 {#part-2-histogram}&quot;">​</a></h3><p>指标直方图经典桶是累计计数，bucket的le代表小于等于边界，不能把_bucket曲线本身叫P95。先对每桶求rate再按le保留聚合，最后使用histogram_quantile(0.95, ...)，结果是基于桶的估计；桶太粗会有误差。平均耗时用rate(_sum)/rate(_count)，不是每秒速率；跨实例分位数不能简单平均。没有请求时分母为零的NaN要明确展示而非假称延迟为零。</p><h3 id="part-2-selfcheck" tabindex="-1">本篇练习与参考解答 <a class="header-anchor" href="#part-2-selfcheck" aria-label="Permalink to &quot;本篇练习与参考解答 {#part-2-selfcheck}&quot;">​</a></h3><p>练习：同一Counter两实例中一台重启，先sum再rate安全吗？</p><details><summary>参考解答</summary><p>不安全。应先对单序列rate识别重置，再sum聚合；聚合后递减可能被另一实例增长掩盖。</p></details><h3 id="part-2-references" tabindex="-1">核对资料与相邻阅读 <a class="header-anchor" href="#part-2-references" aria-label="Permalink to &quot;核对资料与相邻阅读 {#part-2-references}&quot;">​</a></h3><p>本节沿用<a href="#part-1-references">本页资料与示例入口</a>。</p>',29)])])}const g=a(s,[["render",o]]);export{h as __pageData,g as default};
